occ={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
placements=[]
for r in range(6):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if box <= occ: placements.append((box,('square',None,r,c)))
  for missing in box:
   cells=box-{missing}
   if cells <= occ: placements.append((cells,('L',missing,r,c)))
sol=[]
def rec(rem, chosen):
 if not rem:
  sol.append(chosen); return
 cell=min(rem)
 for cells,tag in placements:
  if cell in cells and cells<=rem:
   rec(rem-cells,chosen+[tag])
rec(occ,[])
len(sol),sol[:10]
